  "settings.remoteIm.resilience.notes.noSilentDrop": "Quota / 429 / soft-limit பிழைகள் தெளிவான நகலாக வெளிப்படும் - வெற்றிகரமான சுற்றை ஒருபோதும் கண்டுபிடிக்க முடியாது.",
  "settings.remoteIm.resilience.notes.crashRecovery": "இணைப்பான் செயலிழந்த பிறகு, உரையாடல் வரலாறு வைக்கப்படுகிறது; கேட்கும் போது ரிமோட் சுற்றுகள் மீண்டும் தொடங்கும். உள்ளூர் நிகழ்வு காலவரிசை சிறந்த முயற்சியாகும் (விபத்திற்குப் பிறகு காலியாக இருக்கலாம்).",
  "settings.remoteIm.resilience.empty.channelsRecovering": "இப்போது நேரடி சேனல் இணைப்பு இல்லை — பிரிட்ஜ் மீட்கப்படுகிறது. இணைக்கப்பட்ட சேனல்கள் கீழே பட்டியலிடப்பட்டுள்ளன; ரிட்டர்ன்களைக் கேட்கும்போது அவை மீண்டும் இணைகின்றன.",
  "settings.remoteIm.resilience.empty.channelsRateLimited": "விகிதம்/ஒதுக்கீடு வரம்பு செயலில் இருக்கும்போது நேரடி சேனல் இணைப்பு இல்லை. பிணைக்கப்பட்ட சேனல்கள் பட்டியலிடப்பட்டிருக்கும்; வரம்பு அழிக்கப்பட்ட பிறகு காத்திருக்கவும் அல்லது மீண்டும் இணைக்கவும்.",
  "settings.remoteIm.resilience.empty.channelsNotLinked": "சேனல்கள் கட்டமைக்கப்பட்டுள்ளன ஆனால் இன்னும் இணைக்கப்படவில்லை. இணைப்பை முடிக்க பாலத்தைத் தொடங்கவும் அல்லது சேனலைத் திறக்கவும்.",
  "settings.remoteIm.resilience.empty.timelineRecovering": "மீட்டெடுப்பின் போது உள்ளூர் நிகழ்வுகள் எதுவும் பதிவு செய்யப்படவில்லை. காலப்பதிவு என்பது சாதனம் சார்ந்தது மட்டுமே மற்றும் செயலிழந்த பிறகு ஹோஸ்டிலிருந்து மீண்டும் உருவாக்கப்படவில்லை.",
  "settings.remoteIm.resilience.empty.timelineRateLimited": "இந்த கட்டண வரம்பு எபிசோடில் உள்ளூர் நிகழ்வுகள் இல்லை. மென்மையான வரம்பு பதில்கள் IM பக்கத்தில் நடக்கும்; இந்த பட்டியல் செய்தி உடல்கள் அல்லது இரகசியங்களை ஒருபோதும் சேமிக்காது.",
